import{_ as e,c as a,o,b0 as r}from"./chunks/framework.Dmsv_Tiv.js";const n="/media-docs/assets/f3b8b9f8e9af9b162c5b0f53e83cf74b.D2t8UYGS.png",l="data:image/png;base64,",s="/media-docs/assets/image-20251223184128465.CNwJFxVf.png",d="/media-docs/assets/39670ff0561129b36470ee53e0fa7bd2.DhIuPWSz.png",i="/media-docs/assets/image-20251223184144006.C6bayzi3.png",c="/media-docs/assets/d10f86a42786944f6eaec453492112f8.BFvbYT2X.png",b="/media-docs/assets/ea2b443e845a4ca126270b32281ad6b0.CZQO08hV.png",h="/media-docs/assets/a6826d81a4bd99ed6a35960c4d7d63f0.BZ8DH3gc.png",p="/media-docs/assets/216dba1fca4d77105d8e1dfb7ea24520.C2CcgGtw.png",f="/media-docs/assets/6d9d08b35ee006188bffafa3888a03a0.sNraZ9H4.png",v=JSON.parse('{"title":"LV020-PCM接口简介","description":null,"frontmatter":{"title":"LV020-PCM接口简介","date":"2025-12-22T15:53:57.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/acodec/atransmission/126b1ae7205d22122b20da70","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-22T15:53:57.545Z","fulluuid":"22b20da7001846e6b6a30915ac5267d9","useduuid":"22b20da70"}},"headers":[],"relativePath":"sdoc/acodec/atransmission/126b1ae7205d22122b20da70.md","filePath":"sdoc/25-音频编解码/30-音频传输/LV020-PCM接口简介.md","lastUpdated":1767537778000}'),m={name:"sdoc/acodec/atransmission/126b1ae7205d22122b20da70.md"};function g(u,t,M,C,P,S){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="lv020-pcm接口简介" tabindex="-1">LV020-PCM接口简介 <a class="header-anchor" href="#lv020-pcm接口简介" aria-label="Permalink to &quot;LV020-PCM接口简介&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><blockquote><p>先吐槽一下？？？其实这里整的挺懵的，PCM、I2S、TDM，不同的芯片手册又是支持多种接口，不同的概念在不同的手册中交织，网上的资料也是给人整迷糊。一会是 PCM/TDM 的，一会又是 DSP/PCM 的，尽可能理解吧，这里 <strong>不保证完全正确</strong>，后续发现有误一定要注意更新。</p></blockquote><h3 id="_1-pcm-简介" tabindex="-1">1. PCM 简介 <a class="header-anchor" href="#_1-pcm-简介" aria-label="Permalink to &quot;1. PCM 简介&quot;">​</a></h3><p>PCM (Pulse Code Modulation) 脉冲编码调制是将模拟信号数字化的方法。原理是用一个固定的频率对模拟信号进行采样，采样后的信号在波形上看就像一串连续的幅值不一的脉冲(脉搏似的短暂起伏的电冲击)，把这些脉冲的幅值按一定精度进行量化，这些量化后的数值被连续的输出、传输、处理或记录到存储介质中，所有这些组成了数字音频的产生过程(抽样、量化、编码三个过程)。下图为 4 bit 采样深度的 PCM 数据量化示意图。</p><img src="'+n+'" alt="img" style="zoom:50%;"><p>而这个 PCM，也可以指一种 <strong>数字音频接口</strong>，即说明接口上传输的音频数据通过 PCM 方式采样得到的。在音频领域，PCM 接口常用于板级音频数字信号的传输，与 I2S 相似。PCM 和 I2S 的区别于数据相对于帧时钟（FSYNC/WS）的位置、时钟的极性和帧的长度。其实，<strong>I2S 上传输的也是 PCM 类型的数据</strong>，因此可以说 I2S 不过是 PCM 接口的特例。</p><p>相比于 I2S 接口，PCM 接口应用更加灵活。通过时分复用（TDM, Time Division Multiplexing）方式，PCM 接口支持同时传输多达 N 个（N &gt; 8）声道的数据，减少了管脚数目（实际上是减少 I2S 的“组”数，因为每组 I2S 只能传输两声道数据嘛）。TDM 不像 I2S 有统一的标准，不同的 IC 厂商在应用 TDM 时可能略有差异，这些差异表现在时钟的极性、声道配置的触发条件和对闲置声道的处理等。</p><blockquote><p>Tips：PCM 采用时分复用的方式，就是 TDM。</p></blockquote><h3 id="_2-tdm-简介" tabindex="-1">2. TDM 简介 <a class="header-anchor" href="#_2-tdm-简介" aria-label="Permalink to &quot;2. TDM 简介&quot;">​</a></h3><p>最开始出现的 I2S 只能传输左右两通道的数据，后来为了传输多通道数据，出现了 I2S 的变体，即应用了 TDM（时分复用）模式。协议时序与旧版 I2S 类似，但是出现了 slot（槽）的概念。slot 是指某个通道的一帧数据，数据传输示意图如下：</p><p><img src="'+l+'" alt="image-20251222203537891"></p><p>如上图，TDM 数据传输示意图。 每个音频信号都被分配一个固定的 slot(时间槽)，这些 slot 按顺序排列组成一个帧。每个 slot 的长度相等且固定，可以容纳一个音频信号的数据。通过按照事先约定的顺序轮流填充每个 slot，多个音频信号的数据被交错传输。</p><p>在发送端，音频 TDM 协议将多个音频信号的样本值分别放置在对应的 slot 中。在接收端，协议按照相同的顺序将 slot 的数据取出，并重新还原成原始的音频信号。通过这种方式，多个音频信号可以同时传输在同一个信道上，实现了信道资源的高效利用。</p><blockquote><p>注意：上面提到的 slot 与音频的声道没有直接的对应关系，跟实际芯片平台和 Codec 定义有关，不能简单的讲 slot1 理解位音频数据的第一个声道。例如假设 slot1 的长度位 32bit 时，slot1 可以传输两路 16 位的音频数据。这种灵活性允许在不同的 TDM 实现中，根据具体的需求和约定来确定时间槽的长度以及每个时间槽所承载的音频信号的格式。</p></blockquote><p>很多资料把这个单拎出来成为一个属于 I2S 或者 PCM 的概念，但这样造成了混淆，我们只要理解 TDM 模式可以传输多通道数据即可。</p><h2 id="二、pcm-接口" tabindex="-1">二、PCM 接口 <a class="header-anchor" href="#二、pcm-接口" aria-label="Permalink to &quot;二、PCM 接口&quot;">​</a></h2><p>PCM 接口一般在手册中描述，与 I2S 的区别就是时序图的区别。具体要看芯片手册的定义。我们在这单拿出来让 PCM mode 成为一个接口概念，当然我们也可以认为它就是 I2S 的一个特例。有些地方会叫 TDM/PCM，有些地方会叫 DSP/PCM。</p><h3 id="_1-信号定义" tabindex="-1">1. 信号定义 <a class="header-anchor" href="#_1-信号定义" aria-label="Permalink to &quot;1. 信号定义&quot;">​</a></h3><p>很多资料中将 PCM 接口定义为（PCM-clock、PCM-sync、PCM-in、PCM-out），这可能与 I2S 的接口是对应的，之所以有这种定义可能是历史原因。</p><table><tbody><tr><td align="center"> PCM 信号线 </td> <td align="center"> 说明 </td> <td align="center"> 与 I2S 接口对应情况 </td></tr><tr><td align="center"> PCM_CLK </td> <td align="center"> 数据时钟信号 </td> <td align="center"> SCK </td></tr><tr><td align="center"> PCM_SYNC </td> <td align="center"> 帧同步时钟信号 </td> <td align="center"> WS </td></tr><tr><td align="center"> PCM_IN </td> <td align="center"> 接收数据信号 </td> <td align="center"> SD_IN </td></tr><tr><td align="center"> PCM_OUT </td> <td align="center"> 发送数据信号 </td> <td align="center"> SD_OUT </td></tr></tbody></table><h3 id="_2-时序" tabindex="-1">2. 时序 <a class="header-anchor" href="#_2-时序" aria-label="Permalink to &quot;2. 时序&quot;">​</a></h3><p>我们可以看一下 <a href="https://datasheets.ibselectronics.com/WM8960CGEFL-RV-Cirrus-Logic-datasheet-25356024.pdf" target="_blank" rel="noreferrer">WM8960_DS</a> 的芯片手册，里面有一个 DSP/PCM Mode。根据 SD 相对帧同步时钟 FSYNC 的位置，TDM 分 <strong>两种</strong> 基本模式：</p><ul><li><strong>Mode A:</strong> 数据在 FSYNC 有效后，BCLK 的第 <em><strong>2</strong></em> 个上升沿有效(one clock delay)</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+s+'" style="width:100%;height:auto;" alt="img"></td><td align="center" style="border:none;"><img src="'+d+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table><ul><li><strong>Mode B:</strong> 数据在 FSYNC 有效后，BCLK 的第 <em><strong>1</strong></em> 个上升沿有效(no delay)</li></ul><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+i+'" style="width:100%;height:auto;" alt="img"></td><td align="center" style="border:none;"><img src="'+c+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table><blockquote><p>Tips：</p><p>（1）也可以看 <a href="https://www.nxp.com.cn/docs/en/application-note/AN12202.pdf" target="_blank" rel="noreferrer">AN12202</a>，这个芯片手册就神奇了，PCM、TDM、DSP 分别位于不同的小章节下，哎，反正用的哪款芯片就看他们自己的芯片手册吧。</p><p>（2）由于没有统一标准，不同厂商对 Mode A 和 Mode B 定义可能有所差别，一切都以芯片手册为准。</p></blockquote><h3 id="_3-长短帧同步" tabindex="-1">3. 长短帧同步 <a class="header-anchor" href="#_3-长短帧同步" aria-label="Permalink to &quot;3. 长短帧同步&quot;">​</a></h3><p>在实际应用中，总是以帧同步时钟 FSYNC 的上升沿表示一次传输的开始。帧同步时钟的频率总是等于音频的采样率，比如 44.1 kHz，48 kHz 等。多数应用只用到 FSYNC 的上升沿，而忽略其下降沿。根据不同应用 FSYNC 脉冲宽度的差别，PCM 帧同步时钟模式大致分为两种：</p><ul><li><strong>长帧同步</strong> Long Frame Sync</li><li><strong>短帧同步</strong> Short Frame Sync</li></ul><p>关于长短帧同步、MSB/LSB 和量化深度的区别，对应的 PCM 时序模式，可以参考 CSR BC06 工具：<a href="http://www.wangdali.net/wp-content/uploads/2015/07/pcmconfigv2_1.7z" target="_blank" rel="noreferrer">pcmconfigv2_1</a> ，通过这个工具很容易理解这些变量的含义。</p><h4 id="_3-1-长帧同步" tabindex="-1">3.1 长帧同步 <a class="header-anchor" href="#_3-1-长帧同步" aria-label="Permalink to &quot;3.1 长帧同步&quot;">​</a></h4><p>长帧同步，如左图所示，FSYNC 脉冲宽度等于 1 个 <strong>Slot</strong> 的长度。Slot 在 TDM 中表示的是传输单个声道所占用的位数。</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+b+'" style="width:100%;height:auto;" alt="img"></td><td align="center" style="border:none;"><img src="'+h+'" style="width:80%;height:auto;" alt="img"></td></tr><tr style="border:none;"><td align="center" style="border:none;"> 长帧同步时序图 </td><td align="center" style="border:none;"> 一个 8-bit 长帧同步模式示例 </td></tr></tbody></table><p>右是一个 8bit 长帧同步模式的时序图，图中中是的 TI McASP 接口，这个接口的 TDM 包括 6 个 Slots，即它最多可包括 6 声道数据。</p><p>注意，Slot 的位数并不一定等于音频的量化深度。比如 Slot 可能为 <strong>32 bit</strong>，其中包括 <strong>24 bit</strong> 有效数据位（Audio Word） + <strong>8 bit</strong> 零填充（Zero Padding）。不同厂商对 Slot 的叫法可能有所区别，比如 Circus Logic 称之为 Channel Block。</p><blockquote><p>Tips：TI McASP 在 <a href="https://www.ti.com.cn/cn/lit/an/zhcag05/zhcag05.pdf?ts=1766489972012" target="_blank" rel="noreferrer">AM275x 音频系统设计指南</a> 有介绍</p></blockquote><h4 id="_3-2-短帧同步" tabindex="-1">3.2 短帧同步 <a class="header-anchor" href="#_3-2-短帧同步" aria-label="Permalink to &quot;3.2 短帧同步&quot;">​</a></h4><p>短帧同步，FSYNC 脉冲宽度等于 1 个 BCLK 周期长度。如下图，这是一个 16-bit 短帧同步模式：</p><img src="'+p+'" alt="img" style="zoom:67%;"><h3 id="_4-模式设置" tabindex="-1">4. 模式设置 <a class="header-anchor" href="#_4-模式设置" aria-label="Permalink to &quot;4. 模式设置&quot;">​</a></h3><p>虽然上面说了一堆模式，看似是不同的维度没啥关系的定义，但观察 codec 文档就会发现，从 code 芯片的角度，上面的模式都在一个维度讨论，就是时序图（数据传输格式）不同。</p><p>比如 <a href="https://datasheets.ibselectronics.com/WM8960CGEFL-RV-Cirrus-Logic-datasheet-25356024.pdf" target="_blank" rel="noreferrer">WM8960_DS</a> 芯片：芯片手册说支持下面几种数据传输格式：左对齐，右对齐，I2S 格式，DSP/PCM mode 具体去看时序图。再比如 <a href="https://www.akm.com/content/dam/documents/products/audio/audio-dac/ak4458vn/ak4458vn-en-datasheet.pdf" target="_blank" rel="noreferrer">AK4458</a> 芯片：芯片手册说我支持 PCM 模式 和 DSD 模式，其中 PCM 模式又分为 25 种数据传输格式，这 25 种数据归类为 Normal mode, TDM128 Mode, TDM512 Mode，具体也去看我的时序图。</p><h3 id="_5-时钟频率" tabindex="-1">5. 时钟频率 <a class="header-anchor" href="#_5-时钟频率" aria-label="Permalink to &quot;5. 时钟频率&quot;">​</a></h3><p>FSYNC 的频率等于音频的采样率（例如 44.1 kHz，48 kHz 等）。Frame 每次传输包括所有声道的数据。PCM 采样音频数据量化深度一般在 16-32bit（最常见为 16/24bit）。那么对于 8 声道，每个声道 32bit 音频数据，采样率 48kHz 的系统，TDM 的系统时钟速率为：8 × 32 × 48kHz ＝ 12.288 MHz</p><p>在器件 Datasheet 中可以见到 TDM128/TDM256/TDM 384/TDM512 等说法，数字的含义为单个 TDM 数据帧包含数据的比特数（即帧长）。如上例 8 声道（Channels）32bit 的音频数据，亦称为 TDM256（= 8x32）。TDM 系统时钟速率就可以简单地用采样率乘以 TDM 帧长计算得出。相同的例子，TDM 系统时钟速率：48kHz × 256 ＝ 12.288 MHz</p><p>下表列出系统时钟 SCK/BCLK 和采样率 fs 及 TDM 帧长的关系：</p><img src="'+f+'" alt="img" style="zoom:67%;"><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/zhuwade/article/details/121793160" target="_blank" rel="noreferrer">数字音频接口(I2S, PCM/TDM, PDM)_pdm 接口-CSDN 博客</a></p><p><a href="https://blog.csdn.net/xinshuwei/article/details/86534771" target="_blank" rel="noreferrer">音频常用协议说明 IIS TDM PDM PCM SPDIF 协议解析_pdm 协议-CSDN 博客</a></p><p><a href="https://www.cnblogs.com/Dazz24/p/18807885" target="_blank" rel="noreferrer">I2S 和 TDM 模式详解 - Dazz_24 - 博客园</a></p><p><a href="https://www.cnblogs.com/blogs-of-lxl/p/14722603.html" target="_blank" rel="noreferrer">音频信号类型及协议基础知识 - sheldon_blogs - 博客园</a></p></blockquote>',50)])])}const T=e(m,[["render",g]]);export{v as __pageData,T as default};
